using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){Host.Watch=null;foreach(var w in Find.WindowStack.Windows.OfType<Dialog_MiniGame>().ToList())w.Close();TogetherMatch.Reset();var pair=(Pawn[])Host.State["pair"];var p=pair[0];var o=pair[1];var b=(Thing)Host.State["chess"];var s=GameEntry.SessionFor(b);if(s!=null)GameComponent_Recreation.Current.Remove(s);foreach(var q in pair.Take(2)){q.drafter.Drafted=false;q.jobs.EndCurrentJob(JobCondition.InterruptForced);q.needs.food.CurLevelPercentage=1;q.needs.rest.CurLevelPercentage=1;}var abrasive=DefDatabase<TraitDef>.GetNamed("Abrasive");if(!o.story.traits.HasTrait(abrasive))o.story.traits.GainTrait(new Trait(abrasive));PRMod.Settings.playTogetherBoardFlip=false;GameEntry.Commit(b.TryGetComp<CompMiniGame>().Game,b,p,o,2,false);int start=Find.TickManager.TicksGame,stage=0,last=-1;var f=BindingFlags.Instance|BindingFlags.NonPublic;string log=Host.Root+"/talk-r2.txt";File.WriteAllText(log,"Natural social interactions, Abrasive opponent, superfast game speed; no forced interaction in observation. Board-flip disabled to observe cadence.\n");Host.Watch=()=>{var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&d!=null){stage=1;start=Find.TickManager.TicksGame;}if(stage!=1)return;int e=Find.TickManager.TicksGame-start;var talk=d==null?new List<string>():(List<string>)typeof(Dialog_MiniGame).GetField("talk",f).GetValue(d);if(e/500!=last){last=e/500;File.AppendAllText(log,e+" count="+talk.Count+" open="+(d!=null)+" jobs="+p.CurJobDef+","+o.CurJobDef+"\n");}if(e>10000||d==null){File.AppendAllText(log,"natural lines: "+string.Join(" | ",talk)+"\n");Host.Watch=null;Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.State["talkWindow"]=d;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Observe 4 game hours of natural social activity.";}}

